<?php
header('Content-Type:text/html;charset=UTF-8');
$ROOT=realpath(__DIR__);$SKIP=['.git','node_modules','vendor'];
function blocked($p){global $SKIP;foreach($SKIP as $s)if(preg_match('#(^|/)'.preg_quote($s,'#').'(/|$)#',$p))return true;return false;}
function scan($root){$files=[];$it=new RecursiveIteratorIterator(new RecursiveDirectoryIterator($root,FilesystemIterator::SKIP_DOTS));foreach($it as $f){$p=str_replace('\\','/',substr($f->getPathname(),strlen($root)+1));if(!$p||blocked($p)||$p==='site-wire-live.php')continue;if($f->isFile())$files[$p]=$f->getSize();}ksort($files);$refs=[];$rx=["/\\b(?:require|require_once|include|include_once)\\s*\\(?\\s*['\"]([^'\"]+)['\"]/i","/\\b(?:import|export)\\s+(?:[^'\";]+?\\s+from\\s+)?['\"]([^'\"]+)['\"]/i","/\\b(?:src|href)\\s*=\\s*['\"]([^'\"]+)['\"]/i"];foreach($files as $p=>$size){if($size>700000||!preg_match('/\\.(php|js|mjs|jsx|ts|tsx|css|scss|html|htm|json|xml|svg|yml|yaml|ini|conf|md)$/i',$p))continue;$s=@file_get_contents($root.'/'.$p);if($s===false)continue;foreach($rx as $re){preg_match_all($re,$s,$m);foreach(array_unique($m[1]??[]) as $v){$v=trim(preg_replace('/[#?].*$/','',$v));if(!$v||preg_match('/^(https?:|data:|mailto:|javascript:|#|\/\/)/i',$v))continue;$base=dirname($p);$c=ltrim(str_replace('\\','/',($v[0]==='/'?$v:$base.'/'.$v)),'/');foreach([$c,$c.'.php',$c.'.js',$c.'.css',$c.'.json',$c.'.html',$c.'/index.php',$c.'/index.html'] as $z)if(isset($files[$z])){$refs[]=['from'=>$p,'to'=>$z];break;}}}}return['files'=>array_keys($files),'sizes'=>$files,'refs'=>$refs,'time'=>date('H:i:s')];}
$D=scan($ROOT);if(isset($_GET['pulse'])){header('Content-Type:application/json');echo json_encode(['ok'=>1,'time'=>date('H:i:s')]);exit;}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>SmartToolz Relationship Manager</title><style>
*{box-sizing:border-box}html,body{margin:0;height:100%;background:#071016;color:#dce8ed;font-family:system-ui,sans-serif}.head{height:64px;border-bottom:1px solid #203139;padding:14px 20px;display:flex;align-items:center;justify-content:space-between}.brand{font-weight:700}.brand b{color:#55dfce}.stats{font:9px monospace;color:#70858d}.app{height:calc(100% - 64px);display:flex}.folders{width:260px;border-right:1px solid #203139;padding:16px;overflow:auto}.folders h4{margin:0 0 10px;color:#607780;font:8px monospace}.search{width:100%;padding:9px;background:#09151b;border:1px solid #263d45;border-radius:6px;color:#fff;outline:0;font:9px monospace;margin-bottom:9px}.folder{padding:9px;border-radius:6px;color:#9aaeb5;font:10px monospace;cursor:pointer;display:flex;justify-content:space-between}.folder:hover,.folder.active{background:#102128;color:#64ded2}.count{color:#526b74}.main{flex:1;padding:24px;overflow:auto}.crumb{color:#607780;font:8px monospace;margin-bottom:10px}.toolbar{display:flex;gap:5px;margin-bottom:12px}.filter,.btn{border:1px solid #263d45;background:#09151b;color:#849aa2;border-radius:6px;padding:7px 9px;font:8px monospace;cursor:pointer}.filter.active,.filter:hover,.btn:hover{color:#64ded2;border-color:#55dfce66}.note{color:#4e6872;font:8px monospace;margin-bottom:10px}.file{width:100%;text-align:left;border:1px solid #263d45;background:#0a151b;border-radius:6px;padding:9px 11px;color:#91a5ac;font:9px monospace;cursor:pointer;display:flex;justify-content:space-between;margin-bottom:5px}.file:hover,.file.active{border-color:#55dfce;color:#e9ffff;background:#0d1c22}.right{color:#526d76;font-size:8px}.kind{color:#9a7dff}.empty{color:#526a73;font:10px monospace;padding:30px 0}.relation{position:fixed;z-index:8;right:20px;top:84px;width:330px;background:#09151bf8;border:1px solid #263d45;border-radius:8px;padding:14px;display:none}.relation.show{display:block}.relation h3{margin:7px 0 2px;font-size:13px}.relation .close{float:right;background:none;border:0;color:#71858d;font-size:18px}.tag{color:#59757f;font:7px monospace;letter-spacing:1px}.path{color:#55dfce;font:8px monospace;word-break:break-all}.summary{display:flex;gap:5px;margin-top:10px}.stat{flex:1;background:#0d1c22;border-radius:6px;padding:7px}.stat b{display:block;font:12px monospace}.stat span{font:7px monospace;color:#58717a}.list{margin-top:10px;font:8px monospace;color:#8da1a8;line-height:1.8;max-height:230px;overflow:auto}.bottom{position:fixed;left:280px;bottom:14px;color:#566d76;font:8px monospace}.status{position:fixed;right:20px;bottom:18px;color:#607982;font:8px monospace}.led{display:inline-block;width:6px;height:6px;border-radius:50%;background:#5be5bb;margin-right:6px;box-shadow:0 0 10px #5be5bb}@media(max-width:700px){.folders{width:190px}.main{padding:14px}.bottom{left:205px}.relation{left:205px;right:10px;width:auto}}
</style></head><body><header class="head"><div class="brand"><b>◇</b> SmartToolz Relationship Manager</div><div class="stats"><?php echo count($D['files']);?> files · <?php echo count($D['refs']);?> relations · <span style="color:#55dfce">LIVE</span></div></header><div class="app"><aside class="folders"><h4>FOLDERS</h4><input id="search" class="search" placeholder="Search…"><div id="folderList"></div></aside><main class="main"><div id="crumb" class="crumb">SELECT A FOLDER</div><div class="toolbar"><button class="filter active" data-type="all">ALL</button><button class="filter" data-type="php">PHP</button><button class="filter" data-type="js">JS</button><button class="filter" data-type="css">CSS</button><button class="filter" data-type="other">OTHER</button></div><div id="note" class="note">Choose a folder to keep the view clean.</div><div id="files"><div class="empty">Select a folder to see its files.</div></div></main></div><div id="relation" class="relation"><button id="close" class="close">×</button><div class="tag">FILE RELATIONSHIPS</div><h3 id="rn"></h3><div id="rp" class="path"></div><div class="summary"><div class="stat"><b id="inc">0</b><span>INCOMING</span></div><div class="stat"><b id="out">0</b><span>OUTGOING</span></div><div class="stat"><b id="total">0</b><span>TOTAL</span></div></div><div id="rl" class="list"></div></div><div class="bottom"><button id="home" class="btn">HOME</button> <button id="refresh" class="btn">RESCAN</button> <span id="hb">Server: <?php echo $D['time'];?></span></div><div class="status"><span class="led"></span><b id="status">LIVE</b></div><script>
var DATA=<?php echo json_encode($D,JSON_UNESCAPED_SLASHES|JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT);?>;
var current='', selected='', filter='all';
function el(id){return document.getElementById(id)}
function folders(){var a={};DATA.files.forEach(function(f){var p=f.split('/');if(p.length>1)a[p[0]]=1});return Object.keys(a).sort()}
function directFiles(folder){return DATA.files.filter(function(f){return f.indexOf(folder+'/')===0 && f.substring(folder.length+1).indexOf('/')===-1})}
function typeOK(f){if(filter==='all')return true;var e=(f.split('.').pop()||'').toLowerCase();if(filter==='php')return e==='php';if(filter==='js')return ['js','mjs','jsx','ts','tsx'].indexOf(e)>=0;if(filter==='css')return ['css','scss'].indexOf(e)>=0;return ['php','js','mjs','jsx','ts','tsx','css','scss'].indexOf(e)<0}
function renderFolders(q){var box=el('folderList');box.innerHTML='';q=(q||'').toLowerCase();folders().forEach(function(f){if(q && f.toLowerCase().indexOf(q)<0 && !DATA.files.some(function(x){return x.indexOf(f+'/')===0&&x.toLowerCase().indexOf(q)>=0}))return;var b=document.createElement('div');b.className='folder'+(f===current?' active':'');b.innerHTML='<span>📁 '+f+'</span><span class="count">'+directFiles(f).length+'</span>';b.onclick=function(){openFolder(f)};box.appendChild(b)})}
function openFolder(folder){current=folder;el('crumb').textContent=folder+' /';el('relation').classList.remove('show');var box=el('files');box.innerHTML='';var list=directFiles(folder).filter(typeOK).sort();el('note').textContent=list.length+' direct files · sorted by name';if(!list.length){box.innerHTML='<div class="empty">No files match this filter.</div>';renderFolders(el('search').value);return}list.forEach(function(f){var b=document.createElement('button');b.className='file';var rel=DATA.refs.filter(function(r){return r.from===f||r.to===f}).length;b.innerHTML='<span>▸ '+f.split('/').pop()+'</span><span class="right"><span class="kind">'+fileType(f)+'</span> · '+size(DATA.sizes[f]||0)+' · '+rel+' links</span>';b.onclick=function(){selectFile(f,b)};box.appendChild(b)});renderFolders(el('search').value)}
function fileType(f){var e=(f.split('.').pop()||'').toLowerCase();if(e==='php')return'PHP';if(['js','mjs','jsx','ts','tsx'].indexOf(e)>=0)return'JS';if(['css','scss'].indexOf(e)>=0)return'CSS';return'FILE'}
function size(n){if(n<1024)return n+' B';if(n<1048576)return Math.round(n/1024)+' KB';return(n/1048576).toFixed(1)+' MB'}
function selectFile(f,b){selected=f;document.querySelectorAll('.file').forEach(function(x){x.classList.remove('active')});b.classList.add('active');var incoming=DATA.refs.filter(function(r){return r.to===f});var outgoing=DATA.refs.filter(function(r){return r.from===f});var list=[];incoming.forEach(function(r){list.push('← '+r.from)});outgoing.forEach(function(r){list.push('→ '+r.to)});el('rn').textContent=f.split('/').pop();el('rp').textContent=f;el('inc').textContent=incoming.length;el('out').textContent=outgoing.length;el('total').textContent=incoming.length+outgoing.length;el('rl').innerHTML=list.length?list.slice(0,60).join('<br>'):'No direct relationships';el('relation').classList.add('show')}
document.querySelectorAll('.filter').forEach(function(b){b.onclick=function(){document.querySelectorAll('.filter').forEach(function(x){x.classList.remove('active')});b.classList.add('active');filter=b.getAttribute('data-type');if(current)openFolder(current)}});
el('search').oninput=function(){renderFolders(this.value);if(current)openFolder(current)};el('close').onclick=function(){el('relation').classList.remove('show')};el('home').onclick=function(){current='';selected='';el('crumb').textContent='SELECT A FOLDER';el('note').textContent='Choose a folder to keep the view clean.';el('files').innerHTML='<div class="empty">Select a folder to see its files.</div>';renderFolders('')};el('refresh').onclick=function(){location.reload()};
setInterval(function(){fetch(location.pathname+'?pulse=1&t='+Date.now(),{cache:'no-store'}).then(function(r){return r.json()}).then(function(d){el('hb').textContent='Server: '+d.time;el('status').textContent='LIVE'}).catch(function(){el('hb').textContent='Server: offline';el('status').textContent='OFFLINE'})},3000);
renderFolders('');
</script></body></html>